### Question 2: Terraform Script (Intermediate Level)

**Question:**
You are provisioning an AWS EC2 instance and an S3 bucket using Terraform. The EC2 instance needs to have an IAM Role attached that grants it read-only access to a *specific* S3 bucket. Which set of Terraform resources and configurations correctly achieves this, ensuring proper dependency management for the IAM role and policy?

A.
```terraform
resource "aws_iam_role" "ec2_role" {
  name = "my-ec2-role"
  assume_role_policy = jsonencode({ /* ... EC2 assume role policy ... */ })
}
resource "aws_iam_role_policy" "s3_read_policy" {
  name = "s3-read-policy"
  role = aws_iam_role.ec2_role.id
  policy = jsonencode({ /* ... S3 GetObject policy for bucket ... */ })
}
resource "aws_s3_bucket" "my_bucket" { bucket = "my-unique-app-bucket" }
resource "aws_instance" "my_instance" {
  ami           = "ami-0abcdef1234567890"
  instance_type = "t2.micro"
  iam_instance_profile = aws_iam_role.ec2_role.name
}
```

B.
```terraform
resource "aws_iam_role" "ec2_role" {
  name = "my-ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{ Action = "sts:AssumeRole", Effect = "Allow", Principal = { Service = "ec2.amazonaws.com" } }]
  })
}
resource "aws_iam_policy" "s3_read_policy" {
  name = "s3-read-access-policy"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{ Action = ["s3:GetObject"], Effect = "Allow", Resource = ["${aws_s3_bucket.my_bucket.arn}/*"] }]
  })
}
resource "aws_iam_role_policy_attachment" "attach_s3_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = aws_iam_policy.s3_read_policy.arn
}
resource "aws_s3_bucket" "my_bucket" { bucket = "my-unique-app-bucket" }
resource "aws_iam_instance_profile" "ec2_profile" {
  name = "my-ec2-instance-profile"
  role = aws_iam_role.ec2_role.name
}
resource "aws_instance" "my_instance" {
  ami           = "ami-0abcdef1234567890"
  instance_type = "t2.micro"
  iam_instance_profile = aws_iam_instance_profile.ec2_profile.name
}
```

C.
```terraform
resource "aws_iam_role" "ec2_role" {
  name = "my-ec2-role"
  assume_role_policy = jsonencode({ /* ... EC2 assume role policy ... */ })
}
resource "aws_s3_bucket_policy" "bucket_policy" {
  bucket = aws_s3_bucket.my_bucket.id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{ Effect = "Allow", Principal = { AWS = aws_iam_role.ec2_role.arn }, Action = ["s3:GetObject"], Resource = ["${aws_s3_bucket.my_bucket.arn}/*"] }]
  })
}
resource "aws_s3_bucket" "my_bucket" { bucket = "my-unique-app-bucket" }
resource "aws_instance" "my_instance" {
  ami           = "ami-0abcdef1234567890"
  instance_type = "t2.micro"
  # Missing IAM instance profile attachment
}
```

D.
```terraform
resource "aws_iam_role" "ec2_role" {
  name = "my-ec2-role"
  assume_role_policy = jsonencode({ /* ... EC2 assume role policy ... */ })
}
resource "aws_s3_bucket" "my_bucket" { bucket = "my-unique-app-bucket" }
resource "aws_instance" "my_instance" {
  ami           = "ami-0abcdef1234567890"
  instance_type = "t2.micro"
  iam_instance_profile = aws_iam_role.ec2_role.name
  # Missing IAM policy to grant S3 access
}
```

**Correct Answer: B**

**Explanation:**
*   **Correct (B):** This solution correctly implements the AWS best practice for granting an EC2 instance permissions. It creates an `aws_iam_role` for EC2, defines a separate `aws_iam_policy` with specific S3 read permissions, and uses `aws_iam_role_policy_attachment` to link them. Crucially, it then creates an `aws_iam_instance_profile` to wrap the IAM role, and this instance profile's name is correctly assigned to the `iam_instance_profile` attribute of the `aws_instance`. Terraform implicitly handles the necessary dependencies for creation order.
*   **Incorrect (A):** This option incorrectly attempts to attach the IAM role directly to the EC2 instance using `iam_instance_profile = aws_iam_role.ec2_role.name`. The `iam_instance_profile` argument expects the name of an *instance profile* resource, not directly an IAM role. An `aws_iam_instance_profile` resource is required.
*   **Incorrect (C):** While `aws_s3_bucket_policy` allows the specified IAM role to access the bucket, this option *does not attach the IAM role to the EC2 instance itself*. Without an associated instance profile, the EC2 instance cannot assume the role and thus cannot authenticate to S3.
*   **Incorrect (D):** This option has two main issues. Firstly, it lacks any definition for an IAM policy that grants the necessary S3 read access. Secondly, similar to option A, it incorrectly tries to assign the IAM role name directly to the `iam_instance_profile` attribute, which requires an `aws_iam_instance_profile` resource.

